import sys,re,os,glob
import xml.etree.ElementTree as ET
def bb_obj(p):
    xs=[]
    for l in open(p,errors='ignore'):
        if l.startswith('v '):
            xs.append(list(map(float,l.split()[1:4])))
    return xs
def bb_dae(p):
    t=ET.parse(p); ns={'c':'http://www.collada.org/2005/11/COLLADASchema'}
    pts=[]
    for g in t.iter('{%s}geometry'%ns['c']):
        mesh=g.find('c:mesh',ns)
        if mesh is None: continue
        vin=mesh.find('c:vertices/c:input[@semantic="POSITION"]',ns)
        sid=vin.get('source')[1:]
        for s in mesh.findall('c:source',ns):
            if s.get('id')==sid:
                a=list(map(float,s.find('c:float_array',ns).text.split()))
                pts+= [a[i:i+3] for i in range(0,len(a),3)]
    up=t.find('.//c:up_axis',ns)
    return pts, (up.text if up is not None else None)
for p in sys.argv[1:]:
    if p.endswith('.obj'): pts,up=bb_obj(p),None
    else: pts,up=bb_dae(p)
    mn=[min(v[i] for v in pts) for i in range(3)]; mx=[max(v[i] for v in pts) for i in range(3)]
    print(os.path.relpath(p,'/app/data/models/ships'),up,[round(x,2) for x in mn],[round(x,2) for x in mx])
EOF
cd /app/data/models/ships; python3 -I /tmp/s/bb.py */*col*.{dae,obj} */*_hi*.dae */*-hi.dae */*hi.dae 2>&1 | sort | uniq

