cat > /tmp/s/tag.py <<'EOF'
import sys,os,glob
import xml.etree.ElementTree as ET
import numpy as np
C='{http://www.collada.org/2005/11/COLLADASchema}'
def mat(node):
    M=np.eye(4)
    for ch in node:
        t=ch.tag.replace(C,'')
        v=list(map(float,ch.text.split())) if ch.text else []
        if t=='matrix': M=M@np.array(v).reshape(4,4)
        elif t=='translate': T=np.eye(4);T[:3,3]=v;M=M@T
        elif t=='scale': S=np.diag(v+[1]);M=M@S
        elif t=='rotate':
            x,y,z,a=v;a=np.radians(a);n=np.array([x,y,z]);n/=np.linalg.norm(n)
            K=np.array([[0,-n[2],n[1]],[n[2],0,-n[0]],[-n[1],n[0],0]])
            R=np.eye(3)+np.sin(a)*K+(1-np.cos(a))*K@K;T=np.eye(4);T[:3,:3]=R;M=M@T
    return M
def load(p):
    t=ET.parse(p);r=t.getroot()
    geoms={}
    for g in r.iter(C+'geometry'):
        m=g.find(C+'mesh')
        if m is None: continue
        sid=m.find(C+'vertices/'+C+'input[@semantic="POSITION"]').get('source')[1:]
        for s in m.findall(C+'source'):
            if s.get('id')==sid:
                fa=s.find(C+'float_array')
                a=np.array(list(map(float,(fa.text or '').split())))
                geoms[g.get('id')]=a.reshape(-1,3)
    tags={};pts=[]
    def walk(n,M):
        M=M@mat(n)
        if n.get('name','').startswith('tag_'): tags[n.get('name')]=M[:3,3]
        for ig in n.findall(C+'instance_geometry'):
            g=geoms.get(ig.get('url')[1:])
            if g is not None and len(g): pts.append((np.c_[g,np.ones(len(g))]@M.T)[:,:3])
        for c in n.findall(C+'node'): walk(c,M)
    for vs in r.iter(C+'visual_scene'):
        for n in vs.findall(C+'node'): walk(n,np.eye(4))
    return tags,(np.vstack(pts) if pts else None)
for p in sys.argv[1:]:
    tags,pts=load(p)
    s=os.path.relpath(p,'/app/data/models/ships')
    if 'tag_landing' in tags: print(s,'tag_landing',np.round(tags['tag_landing'],3))
    if pts is not None: print(s,'min',np.round(pts.min(0),3),'max',np.round(pts.max(0),3))
EOF
cd /app/data/models/ships; for f in */*.dae; do python3 -I /tmp/s/tag.py $f 2>/dev/null; done | grep -i "tag_landing\|col"

